var Q1=[
{n:1,q:"La Constitución Española de 1978...",o:{a:"No es una norma jurídica, sino una declaración con valor político.",b:"Es una norma jurídica con un valor supeditado a las leyes de las Cortes Generales.",c:"Es la norma suprema del ordenamiento jurídico.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"c",why:{"c":"La Constitución Española de 1978 es la norma suprema del ordenamiento jurídico español (art. 9.1 CE), a la que están subordinadas todas las demás normas. No es una simple declaración política, sino la norma fundamental y fundacional del Estado."}},
{n:2,q:"En la Constitución Española de 1978, el pluralismo político es...",o:{a:"Un principio que inspira el ordenamiento jurídico.",b:"Un valor superior del ordenamiento jurídico.",c:"Un principio rector de la política social y económica.",d:"Una declaración de intenciones."},correct:"b",why:{"b":"El artículo 1.1 de la CE establece que España propugna como valores superiores de su ordenamiento jurídico la libertad, la justicia, la igualdad y el pluralismo político. Por tanto, el pluralismo político es un valor superior, no un mero principio."}},
{n:3,q:"La Constitución Española de 1978 se fundamenta:",o:{a:"En la indisoluble unidad de la nación española.",b:"En la libertad e igualdad del individuo y de los grupos en que se integra.",c:"En la Monarquía parlamentaria.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{"a":"El artículo 2 de la CE dispone que \'La Constitución se fundamenta en la indisoluble unidad de la Nación española, patria común e indivisible de todos los españoles, y reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones que la integran y la solidaridad entre todas ellas\'."}},
{n:4,q:"La Constitución Española de 1978 proclama que es libre la creación y el ejercicio de su actividad, dentro del respeto a la Constitución y a la Ley. Esta afirmación está referida a:",o:{a:"Las Fuerzas y Cuerpos de Seguridad.",b:"Las Fuerzas Armadas.",c:"Las asociaciones de empresarios.",d:"Los colegios profesionales."},correct:"c",why:{"c":"El artículo 7 de la CE establece que \'Los sindicatos de trabajadores y las asociaciones empresariales contribuyen a la defensa y promoción de los intereses económicos y sociales que les son propios. Su creación y el ejercicio de su actividad son libres dentro del respeto a la Constitución y a la ley.\'"}},
{n:5,q:"La Ley para la Reforma Política...",o:{a:"Contaba con la aprobación tácita del General Franco.",b:"Fue aprobada con la abstención del Gobierno.",c:"Fue impulsada por D. Manuel Fraga.",d:"Se aprobó el 18 de noviembre de 1976."},correct:"d",why:{"d":"La Ley para la Reforma Política fue aprobada por las Cortes franquistas el 18 de noviembre de 1976. Fue impulsada por Adolfo Suárez, no por Manuel Fraga, y supuso el paso de la legalidad franquista a la democracia desde dentro del propio sistema."}},
{n:6,q:"Con respecto a la Ley para la Reforma Política:",o:{a:"Su tramitación y aprobación, de acuerdo con la legalidad franquista vigente, puso fin al franquismo desde su propia legalidad.",b:"Fue impulsada por Adolfo Suárez.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{"c":"Ambas afirmaciones son correctas: la Ley para la Reforma Política utilizó los mecanismos legales del franquismo para desmantelarlo (\'reforma desde la legalidad\'), y fue impulsada por Adolfo Suárez como Presidente del Gobierno."}},
{n:7,q:"En la Constitución Española de 1978 se pueden distinguir:",o:{a:"Un Libro I y un Libro II.",b:"Una parte general y una parte especial.",c:"Una parte orgánica y una parte dogmática.",d:"Todas las respuestas anteriores son correctas."},correct:"c",why:{"c":"La CE se estructura en dos grandes partes: la parte dogmática (Título Preliminar y Título I), que recoge los principios y derechos fundamentales; y la parte orgánica (Títulos II al X), que regula la organización y funcionamiento de los poderes del Estado."}},
{n:8,q:"La parte dogmática de la Constitución Española de 1978 comprende:",o:{a:"El Preámbulo.",b:"El Título Preliminar, el Preámbulo y el Título I.",c:"El Título Preliminar y el Título I.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"c",why:{"c":"La parte dogmática de la CE comprende el Título Preliminar (arts. 1-9) y el Título I (arts. 10-55), dedicado a los derechos y deberes fundamentales. El Preámbulo no forma parte técnicamente de la parte dogmática."}},
{n:9,q:"La parte orgánica de la Constitución Española de 1978 comprende:",o:{a:"Los Títulos II al X.",b:"Los artículos 54 a 169.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{"a":"La parte orgánica de la CE comprende los Títulos II al X (arts. 56-169), que regulan la organización de los poderes del Estado: La Corona, las Cortes Generales, el Gobierno, relaciones entre poderes, poder judicial, economía, organización territorial, Tribunal Constitucional y reforma constitucional."}},
{n:10,q:"La parte orgánica de la Constitución Española de 1978:",o:{a:"Establece cuales son y cómo se forman los órganos fundamentales del Estado.",b:"Establece qué poderes ejercen los órganos fundamentales del Estado.",c:"Establece cuales son los deberes y derechos de los ciudadanos.",d:"Las respuestas a y b son correctas."},correct:"d",why:{"d":"La parte orgánica de la CE establece tanto qué órganos constituyen los poderes fundamentales del Estado y cómo se forman (opción a), como cuáles son sus poderes y funciones (opción b). Ambas afirmaciones son correctas."}},
{n:11,q:"La vigente Constitución española fue aprobada por las Cortes Generales el día:",o:{a:"6 de diciembre de 1978.",b:"27 de octubre de 1978.",c:"31 de octubre de 1978.",d:"27 de diciembre de 1978."},correct:"c",why:{"c":"La Constitución Española fue aprobada por las Cortes Generales (Congreso de los Diputados y Senado) el 31 de octubre de 1978. Posteriormente fue ratificada en referéndum el 6 de diciembre de 1978 y publicada en el BOE el 29 de diciembre de 1978."}},
{n:12,q:"La Constitución Española de 1978 fue ratificada en referéndum por el pueblo español el día:",o:{a:"6 de diciembre de 1978.",b:"27 de diciembre de 1978.",c:"29 de diciembre de 1978.",d:"Ningún de las respuestas anteriores es correcta."},correct:"a",why:{"a":"La CE fue ratificada en referéndum el 6 de diciembre de 1978, fecha que se celebra actualmente como el Día de la Constitución. El 29 de diciembre fue su publicación en el BOE y entrada en vigor."}},
{n:13,q:"La publicación en el B.O.E. de la Constitución Española de 1978 tuvo lugar:",o:{a:"El 27 de diciembre de 1978, entrando en vigor ese mismo día.",b:"El 6 de diciembre de 1978.",c:"El 31 de octubre de 1978.",d:"El 29 de diciembre de 1978."},correct:"d",why:{"d":"La CE fue publicada en el Boletín Oficial del Estado el 29 de diciembre de 1978, fecha en la que también entró en vigor, según lo establecido en su Disposición Final."}},
{n:14,q:"La Constitución de 1978 tiene un total de:",o:{a:"164 artículos.",b:"259 artículos.",c:"169 artículos.",d:"183 artículos."},correct:"c",why:{"c":"La Constitución Española de 1978 consta de 169 artículos, distribuidos en un Título Preliminar y diez Títulos (del I al X), además de cuatro disposiciones adicionales, nueve transitorias, una derogatoria y una final."}},
{n:15,q:"La estructura de la Constitución Española de 1978 es la siguiente:",o:{a:"Un Título Preliminar, diez Títulos, cuatro disposiciones adicionales, nueve disposiciones transitorias, una disposición derogatoria y una disposición final.",b:"Diez Títulos, siete disposiciones adicionales, nueve disposiciones transitorias, una disposición derogatoria y una disposición final.",c:"Diez Títulos, siete capítulos, nueve seccionales, una disposición adicional, y una disposición final.",d:"Un Título Preliminar, diez Títulos, nueve disposiciones adicionales, cuatro disposiciones transitorias, una disposición derogatoria y una disposición final."},correct:"a",why:{"a":"La CE está compuesta por: un Título Preliminar, diez Títulos (I-X), cuatro disposiciones adicionales, nueve disposiciones transitorias, una disposición derogatoria y una disposición final. Esta estructura es un dato clave para las oposiciones."}},
{n:16,q:"En la Constitución Española de 1978 el término \'Fórmula Promulgatoria\' está referido a:",o:{a:"Las palabras con las que el Rey hace pública la Constitución.",b:"La fórmula en la que se indican los principios que se quieren alcanzar.",c:"Las palabras con las que el Rey sanciona la Constitución.",d:"El preámbulo de la misma."},correct:"a",why:{"a":"La Fórmula Promulgatoria es la declaración formal con la que el Jefe del Estado hace pública y da fuerza ejecutiva a la norma. En el caso de la CE de 1978, son las palabras con las que el Rey Juan Carlos I proclamó y promulgó la Constitución ante las Cortes y el pueblo español."}},
{n:17,q:"No está considerado como uno de los siete padres de la Constitución de 1978:",o:{a:"D. Adolfo Suarez González.",b:"D. José Pedro Pérez LLorca.",c:"D. Manuel Fraga Iribarne.",d:"D. Miguel Roca Junyent."},correct:"a",why:{"a":"Adolfo Suárez NO es uno de los siete padres de la Constitución (ponentes constitucionales). Los siete padres son: Gabriel Cisneros, Manuel Fraga, Miguel Herrero, Gregorio Peces Barba, José Pedro Pérez Llorca, Miguel Roca Junyent y Jordi Solé Tura. Suárez fue el Presidente del Gobierno durante el proceso constituyente."}},
{n:18,q:"No está considerado como uno de los siete padres de la Constitución de 1978:",o:{a:"D. Jordi Solé i Turá.",b:"D. Miguel Herrero y Rodriguez de Miñón.",c:"D. Gregorio Peces Barba.",d:"D. Rodolfo Martín Villa."},correct:"d",why:{"d":"Rodolfo Martín Villa NO es uno de los siete padres de la Constitución. Los ponentes constitucionales fueron: Gabriel Cisneros, Manuel Fraga, Miguel Herrero y Rodríguez de Miñón, Gregorio Peces Barba, José Pedro Pérez Llorca, Miguel Roca Junyent y Jordi Solé Tura."}},
{n:19,q:"En el Preámbulo de la Constitución Española de 1978 se describen:",o:{a:"Las palabras con las que el Rey hace pública la Constitución.",b:"La proclamación de los principios, aspiraciones y valores que se quieren alcanzar.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{"b":"El Preámbulo de la CE contiene la proclamación de los principios, aspiraciones y valores que la Nación española quiere alcanzar: justicia, libertad, seguridad, convivencia democrática, progreso, etc. No es la Fórmula Promulgatoria (que es distinta)."}},
{n:20,q:"En el Preámbulo de la Constitución Española de 1978 se dice que:",o:{a:"España es un estado social y democrático de derecho.",b:"La forma política del Estado español es la Monarquía parlamentaria.",c:"Los ciudadanos y los poderes públicos están sujetos a la Constitución y al resto del ordenamiento jurídico.",d:"La Nación española proclama su voluntad de establecer una sociedad democrática avanzada."},correct:"d",why:{"d":"El Preámbulo de la CE proclama la voluntad de la Nación española de establecer \'una sociedad democrática avanzada\'. Las otras afirmaciones (estado social y democrático de derecho, monarquía parlamentaria, sujeción a la Constitución) están en el articulado, no en el Preámbulo."}},
{n:21,q:"En el Preámbulo de la Constitución Española de 1978 se dice que la nación española proclama su voluntad de:",o:{a:"Reconocer y garantizar el derecho a la autonomía de las nacionalidades y regiones.",b:"Consolidar un Estado de Derecho que asegure el imperio de la ley como expresión de la voluntad popular.",c:"Garantizar la convivencia democrática como forma de Estado.",d:"Colaborar en el fortalecimiento de unas relaciones de cooperación con el resto de países de la Unión Europea."},correct:"b",why:{"b":"El Preámbulo proclama la voluntad de consolidar un Estado de Derecho que asegure el imperio de la ley como expresión de la voluntad popular. La mención a la Unión Europea no figura en el Preámbulo (la CE es de 1978, anterior a la adhesión a la CEE)."}},
{n:22,q:"La Constitución Española de 1978 tiene tres títulos que están divididos en capítulos y que son los:",o:{a:"Títulos I, III y V.",b:"Títulos I, III y VIII.",c:"Títulos I, II, III y V.",d:"Títulos I, III, V y VIII."},correct:"b",why:{"b":"Los tres títulos de la CE que están divididos en capítulos son: el Título I (Capítulos 1 a 5), el Título III (Capítulos 1 y 2) y el Título VIII (Capítulos 1, 2 y 3)."}},
{n:23,q:"¿Qué capítulo del Título I de la Constitución consta de dos Secciones?",o:{a:"El Capítulo primero.",b:"El Capítulo segundo.",c:"El Capítulo tercero.",d:"El Título I no tiene Capítulos."},correct:"b",why:{"b":"El Capítulo segundo del Título I (\'Derechos y libertades\') es el único que se divide en dos Secciones: la Sección 1ª (\'De los derechos fundamentales y de las libertades públicas\', arts. 15-29) y la Sección 2ª (\'De los derechos y deberes de los ciudadanos\', arts. 30-38)."}},
{n:24,q:"En los Títulos II a VI de la Constitución Española se contiene:",o:{a:"La parte dogmática de la misma.",b:"Los derechos y libertades de los españoles.",c:"La articulación y competencias de los distintos poderes del Estado.",d:"La organización territorial del Estado."},correct:"c",why:{"c":"Los Títulos II a VI de la CE regulan la parte orgánica del Estado: Título II (La Corona), Título III (Las Cortes Generales), Título IV (El Gobierno y la Administración), Título V (Relaciones entre el Gobierno y las Cortes Generales) y Título VI (El Poder Judicial). En conjunto, articulan los poderes del Estado."}},
{n:25,q:"En la Constitución Española de 1978, \'Economía y Hacienda\' se encuentra en:",o:{a:"El Título VII, artículos 128 a 136.",b:"El Título V, artículos 108 a 116.",c:"El Título VIII, artículos 117 a 136.",d:"El Título VI, artículos 117 a 127."},correct:"a",why:{"a":"El Título VII de la CE se denomina \'Economía y Hacienda\' y abarca los artículos 128 a 136. Regula materias como la subordinación de la riqueza al interés general, la planificación económica, el Banco de España y la Deuda Pública."}},
{n:26,q:"El Título V de la Constitución Española de 1978 se denomina:",o:{a:"Principios Rectores de la Política Social y Económica.",b:"Del Poder Judicial.",c:"De la Organización Territorial del Estado.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"d",why:{"d":"El Título V de la CE se denomina \'De las relaciones entre el Gobierno y las Cortes Generales\' (arts. 108-116). Los Principios Rectores están en el Título I (Capítulo 3), el Poder Judicial en el Título VI y la Organización Territorial en el Título VIII."}},
{n:27,q:"En la Constitución Española de 1978, el epígrafe \'De las Comunidades Autónomas\' da nombre a:",o:{a:"El Capítulo II del Título VIII.",b:"El Capítulo III del Título VIII.",c:"El Capítulo III del Título III.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"b",why:{"b":"El Capítulo III del Título VIII de la CE se denomina \'De las Comunidades Autónomas\' (arts. 143-158). El Título VIII también incluye el Capítulo I (\'Principios generales\') y el Capítulo II (\'De la Administración Local\')."}},
{n:28,q:"Las Disposiciones adicionales y transitorias de la Constitución Española de 1978 se refieren principal y básicamente a:",o:{a:"Ordenación de los distintos poderes.",b:"Ordenación territorial.",c:"Problemas tributarios.",d:"Régimen de la reserva de ley."},correct:"b",why:{"b":"Las disposiciones adicionales y transitorias de la CE se refieren principalmente a cuestiones de ordenación territorial: derechos históricos de los territorios forales, régimen canario, posibles accesos a la autonomía, traspasos de competencias, etc."}},
{n:29,q:"La Disposición derogatoria de la Constitución Española de 1978:",o:{a:"Deroga la Ley para la Reforma Política.",b:"Deroga la Ley de 21 de julio de 1876.",c:"Las respuestas a) y b) son correctas.",d:"Las respuestas a) y b) son incorrectas."},correct:"c",why:{"c":"La Disposición Derogatoria de la CE de 1978 deroga expresamente: la Ley de Reforma Política de 1977, las Leyes Fundamentales del franquismo (incluida la Ley de Principios del Movimiento Nacional de 1958) y la Ley de 21 de julio de 1876 (segunda ley fundamental)."}},
{n:30,q:"La Disposición derogatoria de la Constitución Española de 1978:",o:{a:"Deroga la Ley de 25 de octubre de 1839.",b:"Deroga la Ley de 12 de febrero de 1912.",c:"Las respuestas a) y b) son correctas.",d:"Las respuestas a) y b) son incorrectas."},correct:"a",why:{"a":"La Disposición Derogatoria de la CE también deroga la Ley de 25 de octubre de 1839 (sobre fueros de las Provincias Vascongadas y Navarra), en la parte que pudiera afectar a las provincias de Álava, Guipúzcoa y Vizcaya."}},
{n:31,q:"La Disposición derogatoria de la Constitución Española de 1978:",o:{a:"Deroga cuantas disposiciones se opongan a lo establecido en esta Constitución.",b:"Deroga la Ley de Principios del Movimiento Nacional.",c:"Las respuestas a) y b) son correctas.",d:"Las respuestas a) y b) son incorrectas."},correct:"c",why:{"c":"La Disposición Derogatoria de la CE de 1978 contiene una cláusula general derogatoria (quedan derogadas cuantas disposiciones se opongan a la CE) y deroga expresamente diversas leyes franquistas, entre ellas la Ley de Principios del Movimiento Nacional y otras leyes fundamentales."}},
{n:32,q:"La Constitución ampara y protege los derechos históricos de los territorios forales. Esta expresión se contiene en:",o:{a:"La Disposición Transitoria Primera de la CE de 1978.",b:"La Disposición Adicional Primera de la CE de 1978.",c:"La Disposición Transitoria Tercera de la CE de 1978.",d:"La Disposición Adicional Tercera de la CE de 1978."},correct:"b",why:{"b":"La Disposición Adicional Primera de la CE establece que \'La Constitución ampara y respeta los derechos históricos de los territorios forales\'. Este reconocimiento constitucional es la base jurídica del régimen foral del País Vasco y Navarra."}},
{n:33,q:"La modificación del régimen económico y fiscal del archipiélago canario requerirá informe previo de la Comunidad Autónoma o, en su caso, del órgano provisional autonómico. Esta expresión se contiene en:",o:{a:"La Disposición Transitoria Primera de la CE de 1978.",b:"La Disposición Adicional Primera de la CE de 1978.",c:"La Disposición Transitoria Tercera de la CE de 1978.",d:"La Disposición Adicional Tercera de la CE de 1978."},correct:"d",why:{"d":"La Disposición Adicional Tercera de la CE se refiere al régimen económico y fiscal específico del archipiélago canario, reconociendo sus especialidades y estableciendo que cualquier modificación requerirá informe previo de la Comunidad Autónoma de Canarias."}},
{n:34,q:"La Constitución Española entró en vigor el mismo día de su publicación en el BOE, según lo establecido:",o:{a:"En su Disposición Adicional Novena.",b:"En su Título X.",c:"En su Disposición Final.",d:"En su Disposición Adicional Cuarta."},correct:"c",why:{"c":"La Disposición Final de la CE establece que \'Esta Constitución entrará en vigor el mismo día de la publicación de su texto oficial en el Boletín Oficial del Estado\', lo que tuvo lugar el 29 de diciembre de 1978."}},
{n:35,q:"Una de las características formales de la Constitución Española de 1978 es:",o:{a:"Estar escrita y codificada en un texto único.",b:"Ser de origen popular.",c:"Ser rígida.",d:"Todas las citadas en las respuestas anteriores son características formales de nuestra Constitución."},correct:"d",why:{"d":"La CE de 1978 reúne todas las características formales señaladas: está escrita y codificada en un texto único; es de origen popular (fue ratificada en referéndum por el pueblo); y es rígida (su reforma requiere procedimientos especiales más exigentes que la ley ordinaria)."}},
{n:36,q:"De acuerdo con el contenido de la Constitución Española de 1978, indique cual de las siguientes frases es incorrecta.",o:{a:"Todo el contenido del Título Preliminar son principios fundamentales.",b:"Los principios fundamentales están formados por valores que informan la totalidad del texto constitucional.",c:"Los principios fundamentales informan la totalidad de la actividad del Estado.",d:"No todos los principios fundamentales se contienen en el Título Preliminar."},correct:"a",why:{"a":"No todo el contenido del Título Preliminar son principios fundamentales. El Título Preliminar incluye también normas organizativas (sobre partidos políticos, sindicatos, Fuerzas Armadas, lenguas, capitalidad, etc.) que van más allá de los meros principios fundamentales."}},
{n:37,q:"Según la Constitución Española de 1978, España se constituye en:",o:{a:"Un Estado Social y Descentralizado de Derecho.",b:"Un Estado Social y Democrático de Derecho.",c:"Un Estado laico, monárquico y de Derecho.",d:"Un Estado Social, Laico, Monárquico y de Derecho."},correct:"b",why:{"b":"El artículo 1.1 de la CE proclama que \'España se constituye en un Estado social y democrático de Derecho, que propugna como valores superiores de su ordenamiento jurídico la libertad, la justicia, la igualdad y el pluralismo político\'."}},
{n:38,q:"El Estado español propugna, como valores superiores de su ordenamiento jurídico:",o:{a:"La libertad, la justicia, la igualdad y el pluralismo político.",b:"La libertad, la justicia, la igualdad, la democracia y el pluralismo político.",c:"La libertad, la justicia, la igualdad, la democracia, el bienestar social y el pluralismo político.",d:"La libertad, la justicia, la igualdad, la solidaridad y el pluralismo político."},correct:"a",why:{"a":"Según el artículo 1.1 CE, los cuatro valores superiores del ordenamiento jurídico español son: la libertad, la justicia, la igualdad y el pluralismo político. La democracia, el bienestar social y la solidaridad no figuran en esta lista, aunque sí en otros preceptos."}},
{n:39,q:"Los principios básicos contenidos en la Constitución Española de 1978:",o:{a:"Se encuentran recogidos en el Título I.",b:"Indican cómo se pretende y cómo se quiere que sea el régimen del Estado.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{"b":"Los principios básicos de la CE indican cómo se pretende y se quiere que sea el régimen del Estado (Estado social y democrático de Derecho, Monarquía parlamentaria, valores superiores, etc.). Se encuentran principalmente en el Título Preliminar, no en el Título I."}},
{n:40,q:"Según la Constitución Española de 1978, la soberanía nacional reside en:",o:{a:"Los poderes del Estado.",b:"El Estado de Derecho.",c:"El pueblo español.",d:"La Monarquía."},correct:"c",why:{"c":"El artículo 1.2 CE establece que \'La soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado\'. Esta es la formulación del principio democrático en la Constitución española."}},
{n:41,q:"Según el art.2 de su Título Preliminar, la Constitución Española de 1978 se fundamenta:",o:{a:"En el pueblo español.",b:"En la unidad de la Nación.",c:"En el Estado de las autonomías.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"d",why:{"d":"El art. 2 CE establece que \'La Constitución se fundamenta en la indisoluble unidad de la Nación española, patria común e indivisible de todos los españoles\'. Ninguna de las opciones recoge exactamente esto: la opción b dice \'unidad de la Nación\' sin la referencia a la indisolubilidad."}},
{n:42,q:"Según el art.2 de su Título Preliminar, la Constitución Española de 1978 se fundamenta:",o:{a:"En el pueblo español.",b:"En la indisoluble unidad de la Nación española, patria común e indivisible de todos los españoles.",c:"En el Estado Social y Democrático de Derecho.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{"b":"El artículo 2 de la CE establece expresamente que \'La Constitución se fundamenta en la indisoluble unidad de la Nación española, patria común e indivisible de todos los españoles\'. Esta es la formulación exacta del precepto."}},
{n:43,q:"Según el art.2 de su Título Preliminar, la Constitución Española de 1978 reconoce y garantiza el derecho a:",o:{a:"La indisoluble unidad de la nación española.",b:"La soberanía nacional de la que emanan los poderes del Estado.",c:"La justicia, la libertad, la igualdad y el pluralismo político.",d:"La autonomía de las nacionalidades y regiones que integran la nación y la solidaridad entre todas ellas."},correct:"d",why:{"d":"El art. 2 CE, además de fundamentarse en la unidad de la Nación, \'reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones que la integran y la solidaridad entre todas ellas\'."}},
{n:44,q:"Según la Constitución Española de 1978, el castellano es la lengua oficial del Estado Español y todos los españoles:",o:{a:"Tienen el deber de conocerla y de usarla.",b:"Tienen el deber de conocerla y el derecho de usarla.",c:"Tienen el derecho de no usarla cuando exista otra lengua oficial en la Comunidad Autónoma.",d:"Las respuestas b) y c) son correctas."},correct:"b",why:{"b":"El artículo 3.1 CE establece que \'El castellano es la lengua española oficial del Estado. Todos los españoles tienen el deber de conocerla y el derecho a usarla\'. Hay deber de conocerla pero solo derecho (no deber) de usarla."}},
{n:45,q:"Además del castellano, las demás lenguas españolas serán también oficiales:",o:{a:"Si así lo reconocen las Cortes mediante ley orgánica y por motivos de interés nacional.",b:"En las Comunidades Autónomas que se constituyan al amparo del artículo 151 de la Constitución Española.",c:"En las respectivas Comunidades Autónomas de acuerdo con sus respectivos Estatutos.",d:"Cuando así lo disponga la ley."},correct:"c",why:{"c":"El artículo 3.2 CE establece que \'Las demás lenguas españolas serán también oficiales en las respectivas Comunidades Autónomas de acuerdo con sus Estatutos\'. La oficialidad de las lenguas cooficiales se establece en los Estatutos de Autonomía."}},
{n:46,q:"La riqueza de las distintas modalidades lingüísticas de España es un patrimonio cultural que será objeto de:",o:{a:"Estudio y promoción.",b:"Respeto en la Constitución y en los Tratados Internacionales.",c:"Especial atención por parte de los poderes públicos.",d:"Especial respeto y protección."},correct:"d",why:{"d":"El artículo 3.3 CE establece que \'La riqueza de las distintas modalidades lingüísticas de España es un patrimonio cultural que será objeto de especial respeto y protección\'. Las modalidades lingüísticas (dialectos, variantes) reciben esta protección aunque no sean lenguas oficiales."}},
{n:47,q:"La bandera de España se utilizará:",o:{a:"En todas las sedes de la Administración General del Estado.",b:"De la forma que reglamentariamente se determine.",c:"En edificios públicos y en actos oficiales.",d:"En los actos y celebraciones que establezca una ley orgánica."},correct:"c",why:{"c":"El artículo 4.1 CE establece que la bandera de España estará en los edificios públicos y en los actos oficiales. El artículo 4 define la bandera como de tres franjas horizontales, roja, amarilla y roja."}},
{n:48,q:"Los Estatutos de Autonomía podrán reconocer banderas y enseñas propias de las Comunidades Autónomas y éstas se utilizarán, junto a la bandera de España:",o:{a:"En sus edificios públicos y en sus actos oficiales.",b:"De la forma que establezca una ley orgánica.",c:"Exclusivamente en sus edificios públicos.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"a",why:{"a":"El artículo 4.2 CE permite que los Estatutos de Autonomía reconozcan banderas y enseñas propias de las CC.AA., que se utilizarán junto a la bandera española en sus edificios públicos y en sus actos oficiales."}},
{n:49,q:"¿En qué artículo de la Constitución consta que la villa de Madrid es la capital del Estado?",o:{a:"En el artículo 5.",b:"En el artículo 6.",c:"En el artículo 4.",d:"En el artículo 3."},correct:"a",why:{"a":"El artículo 5 de la CE establece que \'La capital del Estado es la villa de Madrid\'. Este breve artículo forma parte del Título Preliminar."}},
{n:50,q:"En la Constitución Española de 1978, los sindicatos de trabajadores y las asociaciones empresariales:",o:{a:"Estarán limitados en su creación.",b:"Contribuyen a la formación de la voluntad popular.",c:"Serán cauce de participación en los intereses sociales.",d:"Contribuyen a la defensa y promoción de los intereses económicos y sociales que les son propios."},correct:"d",why:{"d":"El artículo 7 CE establece que \'Los sindicatos de trabajadores y las asociaciones empresariales contribuyen a la defensa y promoción de los intereses económicos y sociales que les son propios\'. Son los partidos políticos (art. 6) los que contribuyen a la formación de la voluntad popular."}},
{n:51,q:"La creación y el ejercicio de la actividad de los sindicatos de trabajadores y de las asociaciones empresariales son:",o:{a:"Objeto de especial respeto y protección.",b:"Una forma de expresión del pluralismo político.",c:"Libres, dentro del respeto a la Constitución y a la ley.",d:"Expresión de la voluntad popular."},correct:"c",why:{"c":"El artículo 7 CE establece que la creación y el ejercicio de la actividad de los sindicatos y asociaciones empresariales \'son libres dentro del respeto a la Constitución y a la ley\'. Su estructura interna y funcionamiento deberán ser democráticos."}},
{n:52,q:"La estructura interna y funcionamiento de los sindicatos de trabajadores y de las asociaciones empresariales deberán ser:",o:{a:"Libres, dentro del respeto a la Constitución y la ley.",b:"Democráticos.",c:"Regulados por una ley orgánica.",d:"Representativos."},correct:"b",why:{"b":"El artículo 7 CE exige que la estructura interna y el funcionamiento de los sindicatos y asociaciones empresariales sean democráticos. Esto se desarrolla en la Ley Orgánica de Libertad Sindical y en la normativa de asociaciones empresariales."}},
{n:53,q:"Las funciones y la organización de los sindicatos están regulados en la Constitución Española de 1978, en su artículo:",o:{a:"4.",b:"6.",c:"8.",d:"7."},correct:"d",why:{"d":"El artículo 7 de la CE regula los sindicatos de trabajadores y las asociaciones empresariales. El art. 4 es sobre la bandera, el art. 6 sobre los partidos políticos y el art. 8 sobre las Fuerzas Armadas."}},
{n:54,q:"Los principios básicos generales de nuestra Constitución, se encuentran recogidos en su:",o:{a:"Artículo 8.",b:"Artículo 10.",c:"Artículo 9.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"c",why:{"c":"El artículo 9 CE recoge los principios básicos generales: sujeción de ciudadanos y poderes públicos a la Constitución, principio de legalidad, jerarquía normativa, publicidad normativa, irretroactividad, seguridad jurídica, responsabilidad e interdicción de la arbitrariedad. No es el art. 8 (Fuerzas Armadas) ni el art. 10 (dignidad de la persona)."}},
{n:55,q:"El principio que autoriza a los ciudadanos a llevar a cabo todas aquellas actividades que la ley no prohíba o cuyo ejercicio no esté subordinado a requisitos o condiciones es:",o:{a:"La libertad.",b:"La igualdad.",c:"La justicia.",d:"La democracia."},correct:"a",why:{"a":"El principio de libertad es el que permite a los ciudadanos actuar libremente en todo aquello que la ley no prohíba. Este principio se recoge como valor superior en el art. 1.1 CE y se concreta en múltiples derechos fundamentales del Título I."}},
{n:56,q:"Conforme a lo previsto en la Constitución, no cabe discriminación alguna por razón de:",o:{a:"Raza, sexo, edad religión, opinión o cualquier otra condición o circunstancia personal o social.",b:"Nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.",c:"Nacimiento, edad, sexo, raza, pobreza, religión, opinión o cualquier otra condición o circunstancia personal o social.",d:"Nacimiento, sexo, raza, estado civil, religión, opinión, vecindad, o cualquier otra condición o circunstancia personal o social."},correct:"b",why:{"b":"El artículo 14 CE establece que los españoles son iguales ante la ley, sin que pueda prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social. El texto exacto incluye \'nacimiento\' pero no \'edad\' o \'pobreza\' de forma expresa."}},
{n:57,q:"Los partidos políticos concurren a la formación y manifestación de la voluntad popular y son instrumento fundamental para:",o:{a:"La participación ciudadana.",b:"La participación política.",c:"La actividad económica.",d:"La participación en la Administración de la Justicia."},correct:"b",why:{"b":"El artículo 6 CE establece que \'Los partidos políticos expresan el pluralismo político, concurren a la formación y manifestación de la voluntad popular y son instrumento fundamental para la participación política.\' Son instrumento de participación política, no ciudadana en general."}},
{n:58,q:"Las funciones atribuidas a las Fuerzas Armadas se describen en el:",o:{a:"Título Preliminar de la Constitución.",b:"Título I de la Constitución.",c:"Títulos II de la Constitución.",d:"Preámbulo de la Constitución."},correct:"a",why:{"a":"Las Fuerzas Armadas están reguladas en el artículo 8 de la CE, que forma parte del Título Preliminar. El art. 8 establece su misión: garantizar la soberanía e independencia de España, defender su integridad territorial y el ordenamiento constitucional."}},
{n:59,q:"Las Fuerzas Armadas, constituidas por el Ejército de Tierra, Armada y Ejército del Aire, tienen como misión:",o:{a:"Garantizar la victoria en caso de guerra.",b:"Garantizar la defensa de España, frente a quienes pretendan destruirla con sus ideas u opiniones.",c:"Garantizar la integridad estatal y del Gobierno de la Nación.",d:"Garantizar la soberanía e independencia de España, defender su integridad territorial y el ordenamiento constitucional."},correct:"d",why:{"d":"El artículo 8.1 CE establece la triple misión de las Fuerzas Armadas: \'garantizar la soberanía e independencia de España, defender su integridad territorial y el ordenamiento constitucional\'. No es la defensa del Gobierno ni la victoria en guerras."}},
{n:60,q:"Las bases de la organización militar, conforme a los principios de la Constitución, deberán regularse mediante:",o:{a:"Ley orgánica.",b:"Ley ordinaria.",c:"Ley de Bases.",d:"Decreto Ley."},correct:"a",why:{"a":"El artículo 8.2 CE establece que \'Una ley orgánica regulará las bases de la organización militar conforme a los principios de la presente Constitución\'. La Defensa Nacional y las Fuerzas Armadas requieren ley orgánica por afectar a derechos fundamentales."}},
{n:61,q:"Según la Constitución Española de 1978, corresponde a los poderes públicos promover las condiciones para que la libertad y la igualdad del individuo y de los grupos en que se integra:",o:{a:"Sean justas.",b:"Sean reales y efectivas.",c:"Sean equitativas.",d:"Sean objeto de especial respeto y protección."},correct:"b",why:{"b":"El artículo 9.2 CE establece que \'corresponde a los poderes públicos promover las condiciones para que la libertad y la igualdad del individuo y de los grupos en que se integra sean reales y efectivas\'. Esto consagra la igualdad material frente a la mera igualdad formal."}},
{n:62,q:"Según la Constitución Española de 1978, corresponde a los poderes públicos remover los obstáculos que impidan o dificulten el disfrute de los derechos y libertades del ciudadano y facilitar:",o:{a:"La participación de todos los ciudadanos en la vida política, económica, cultural y social.",b:"El acceso en condiciones de igualdad a la riqueza que genere el Estado.",c:"La solidaridad entre las distintas partes del territorio y la distribución equitativa de los beneficios que se generen.",d:"El acceso a una vivienda digna y adecuada."},correct:"a",why:{"a":"El artículo 9.2 CE manda a los poderes públicos facilitar \'la participación de todos los ciudadanos en la vida política, económica, cultural y social\'. Este mandato constitucional tiene un contenido de igualdad material y de democracia participativa."}},
{n:63,q:"La igualdad material del art. 9.2 de la Constitución Española:",o:{a:"No impide que puedan tenerse en cuenta diferentes situaciones que hayan de ser objeto de un tratamiento distinto.",b:"Se concibe como una igualdad de trato.",c:"Implica que a dos supuestos de hecho iguales se les aplican las mismas consecuencias.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"a",why:{"a":"La igualdad material del art. 9.2 CE no impide tratar diferente lo que es diferente (discriminación positiva, medidas de acción positiva). El Tribunal Constitucional ha declarado que la igualdad no prohíbe toda diferencia de trato, sino solo las arbitrarias o injustificadas."}},
{n:64,q:"La igualdad supone que:",o:{a:"Ante situaciones de hechos iguales deban aplicarse los precedentes legislativos en la materia siempre que no vulneren la equidad.",b:"Ante situaciones de injusticia patente se puede recurrir a instancias judiciales en busca de amparo.",c:"Ante situaciones de hecho iguales deben aplicarse consecuencias jurídicas también iguales.",d:"Todas las respuestas anteriores son incorrectas."},correct:"c",why:{"c":"El principio de igualdad supone que situaciones de hecho iguales deben tener consecuencias jurídicas también iguales. Este es el núcleo del principio: a igual supuesto, igual consecuencia, sin discriminaciones arbitrarias."}},
{n:65,q:"Con relación al principio de igualdad, el Tribunal Constitucional ha determinado:",o:{a:"Que este principio prohíbe cualquier diferencia de trato.",b:"Que la igualdad que la Constitución consagra puede entenderse dentro o fuera de la legalidad.",c:"Que el legislador no puede diferenciar situaciones para darles un tratamiento diverso.",d:"Que no resulta discriminatoria la acción de favorecimiento que los poderes públicos llevan a cabo para determinados colectivos históricamente preteridos o marginados."},correct:"d",why:{"d":"El TC ha declarado que las acciones positivas o de favorecimiento en favor de colectivos históricamente marginados (mujeres, personas con discapacidad, minorías étnicas) no vulneran el principio de igualdad, sino que son instrumentos de su realización material."}},
{n:66,q:"El Tribunal Constitucional ha determinado que infringir la libertad de creación de partidos políticos es conculcar el derecho a...",o:{a:"El sufragio activo.",b:"El sufragio pasivo.",c:"La participación política.",d:"La formación de la voluntad popular."},correct:"d",why:{"d":"Según el TC, los partidos políticos son instrumentos fundamentales para la formación y manifestación de la voluntad popular (art. 6 CE). Impedir su creación vulnera este derecho fundamental a la formación de la voluntad popular en un Estado democrático."}},
{n:67,q:"El artículo 9.3 de la Constitución Española recoge los principios informadores del ordenamiento jurídico español. Indique cuál de los siguientes no está recogido en dicho precepto:",o:{a:"Principio de legalidad.",b:"Principio de libertad religiosa.",c:"Principio de publicidad de las normas.",d:"Principio de interdicción en la arbitrariedad de los poderes públicos."},correct:"b",why:{"b":"El art. 9.3 CE recoge: legalidad, jerarquía normativa, publicidad de las normas, irretroactividad de disposiciones sancionadoras no favorables, seguridad jurídica, responsabilidad de los poderes públicos e interdicción de la arbitrariedad. El principio de libertad religiosa está en el art. 16 CE, no en el 9.3."}},
{n:68,q:"La interdicción de la arbitrariedad de los poderes públicos significa:",o:{a:"Que los poderes públicos gozan de autonomía.",b:"Que los poderes públicos pueden actuar de forma arbitraria.",c:"Que a los poderes públicos se les prohíbe taxativamente actuar con arbitrariedad.",d:"Que la arbitrariedad debe constituir el funcionamiento normal de los poderes públicos."},correct:"c",why:{"c":"La interdicción de la arbitrariedad (art. 9.3 CE) prohíbe a los poderes públicos actuar de forma caprichosa, sin justificación racional o contraria a los derechos. Las decisiones de los poderes públicos deben estar motivadas y ser proporcionales."}},
{n:69,q:"Conforme al art.10.1 de la Constitución, son fundamentos del orden político y de la paz social:",o:{a:"La convivencia democrática y el Estado de Derecho.",b:"El estado social y democrático de derecho.",c:"La dignidad de la persona y los derechos fundamentales.",d:"La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás."},correct:"d",why:{"d":"El art. 10.1 CE establece que \'La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás son fundamento del orden político y de la paz social\'. Todos los elementos citados en d son los fundamentos."}},
{n:70,q:"Están sujetos a la Constitución y al resto del ordenamiento jurídico:",o:{a:"Los ciudadanos.",b:"Los poderes públicos.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{"c":"El artículo 9.1 CE establece que \'Los ciudadanos y los poderes públicos están sujetos a la Constitución y al resto del ordenamiento jurídico\'. La sujeción es para todos: tanto los ciudadanos como los poderes del Estado."}},
{n:71,q:"Facilitar la participación de todos los ciudadanos en la vida política, económica, cultural y social es una obligación que, según la Constitución Española, corresponde:",o:{a:"Al Estado.",b:"A las instituciones del Estado.",c:"A los poderes públicos.",d:"A las Comunidades Autónomas."},correct:"c",why:{"c":"El artículo 9.2 CE establece que esta obligación corresponde a \'los poderes públicos\', expresión más amplia que \'el Estado\' o \'las instituciones del Estado\', ya que incluye todas las Administraciones Públicas (estatal, autonómica y local)."}},
{n:72,q:"Indique cual de los siguientes principios no está garantizado por el artículo 9.3 de la Constitución Española:",o:{a:"La seguridad jurídica.",b:"La jerarquía normativa.",c:"La responsabilidad.",d:"La dignidad de la persona."},correct:"d",why:{"d":"El artículo 9.3 CE garantiza: legalidad, jerarquía normativa, publicidad, irretroactividad, seguridad jurídica, responsabilidad e interdicción de la arbitrariedad. La dignidad de la persona NO está en el art. 9.3, sino en el art. 10.1 CE como fundamento del orden político."}},
{n:73,q:"En la Constitución Española de 1978, la reforma constitucional se contempla en:",o:{a:"La disposición adicional primera.",b:"La disposición transitoria primera.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{"d":"La reforma constitucional se regula en el Título X de la CE (arts. 166-169), no en las disposiciones adicionales ni transitorias. Las disposiciones adicionales y transitorias regulan cuestiones de derecho transitorio y organización territorial."}},
{n:74,q:"La reforma de la Constitución Española, efectuada el 27 de agosto de 1992, afectó a su artículo:",o:{a:"13.1.",b:"12.3.",c:"13.2.",d:"14.3."},correct:"c",why:{"c":"La primera reforma de la CE de 1978 se produjo el 27 de agosto de 1992, modificando el artículo 13.2 para permitir que los ciudadanos de la Unión Europea pudieran ser elegibles en las elecciones municipales en España, según las exigencias del Tratado de Maastricht."}},
{n:75,q:"La segunda reforma de la Constitución Española de 1978...",o:{a:"Afectó a su artículo 13.2.",b:"Se produjo el 27 de septiembre de 2011.",c:"Se produjo por exigencias del Tratado de Maastricht.",d:"Las respuestas a y c son correctas."},correct:"b",why:{"b":"La segunda reforma de la CE se produjo el 27 de septiembre de 2011 (publicada en el BOE el mismo día), modificando el artículo 135 para introducir el principio de estabilidad presupuestaria y el límite al déficit estructural de las Administraciones Públicas."}},
{n:76,q:"La segunda reforma de la Constitución Española de 1978 se produjo el 27 de septiembre de 2011, que afectó al artículo:",o:{a:"154.",b:"135.",c:"136.",d:"153."},correct:"b",why:{"b":"La segunda reforma constitucional modificó el artículo 135 CE, que regula el principio de estabilidad presupuestaria. Esta reforma, impulsada por el Gobierno de Zapatero por exigencias europeas, introdujo el límite constitucional al déficit y a la deuda pública."}},
{n:77,q:"La iniciativa de reforma de la Constitución Española corresponde en exclusiva:",o:{a:"Al Gobierno y al Congreso de los Diputados.",b:"A la iniciativa popular.",c:"Al Gobierno, al Congreso, al Senado, o a las Asambleas Legislativas de las Comunidades Autónomas.",d:"A las Cortes Generales."},correct:"c",why:{"c":"El artículo 166 CE establece que la iniciativa de reforma constitucional se ejercerá por el Gobierno, el Congreso de los Diputados, el Senado o las Asambleas Legislativas de las CCAA. Está expresamente excluida la iniciativa popular (art. 166 en relación con el 87.3)."}},
{n:78,q:"Las Asambleas de las Comunidades Autónomas podrán solicitar la reforma de la Constitución mediante:",o:{a:"Un proyecto de ley remitido a las Cortes.",b:"Una proposición de ley remitida al Senado.",c:"La solicitud al Gobierno de la adopción de un proyecto de ley o remitiendo a la Mesa del Congreso una proposición de ley.",d:"Una proposición de ley remitida al Gobierno."},correct:"c",why:{"c":"El artículo 87.2 CE, aplicable a la reforma constitucional por remisión del art. 166, establece que las Asambleas de las CCAA pueden solicitar al Gobierno la adopción de un proyecto de ley o remitir a la Mesa del Congreso una proposición de ley."}},
{n:79,q:"¿Cuándo podrá llevarse a cabo una reforma de la Constitución?",o:{a:"Siempre que lo solicite el Gobierno.",b:"Cuando dicha reforma sea ratificada en referéndum.",c:"Cuando no esté declarado el estado de alarma, excepción o sitio.",d:"Siempre que lo solicite el Gobierno y dicha reforma sea ratificada en referéndum por el pueblo."},correct:"c",why:{"c":"El artículo 169 CE establece que la reforma constitucional no podrá iniciarse en tiempo de guerra ni cuando esté vigente alguno de los estados del artículo 116 (alarma, excepción o sitio). Por tanto, solo podrá llevarse a cabo cuando no estén declarados estos estados."}},
{n:80,q:"La reforma constitucional, según lo previsto en el art.169 de la Constitución de 1978, no podrá iniciarse:",o:{a:"En tiempo de guerra.",b:"Durante un periodo de recesión económica.",c:"Cuando esté vigente alguno de los estados previstos en el art.136 de la Constitución.",d:"En ninguno de los casos citados en las respuestas anteriores."},correct:"a",why:{"a":"El artículo 169 CE prohíbe iniciar la reforma constitucional en tiempo de guerra. También lo prohíbe cuando estén vigentes los estados del art. 116 (alarma, excepción o sitio), pero la recesión económica no es un impedimento constitucional. La opción c tiene un error: dice art. 136 cuando debería ser el 116."}},
{n:81,q:"¿Qué preceptos constitucionales pueden ser objeto de reforma?",o:{a:"Todos.",b:"Todos, con excepción de la Sección 1ª del capítulo 2º del Título I.",c:"Todos, salvo los contenidos en el Título II.",d:"Los que constituyen la parte orgánica de la Constitución."},correct:"a",why:{"a":"Todos los preceptos constitucionales pueden ser objeto de reforma, sin excepción. Lo que varía es el procedimiento: algunos requieren el procedimiento agravado del art. 168 (materias especialmente protegidas) y otros el ordinario del art. 167."}},
{n:82,q:"En la Constitución Española de 1978, las materias que gozan de especial protección, a efectos de reforma constitucional, son las contenidas en:",o:{a:"Los Títulos Preliminar, I, II y III.",b:"Los Títulos I y II.",c:"Los Títulos Preliminar, I y II.",d:"Los Títulos Preliminar, I (en su Capítulo 2º, Sección 1ª) y II."},correct:"d",why:{"d":"Las materias de especial protección constitucional (art. 168 CE) son el Título Preliminar, el Título II (La Corona) y la Sección 1ª del Capítulo 2º del Título I (derechos fundamentales y libertades públicas, arts. 15-29). No todo el Título I goza de esta protección reforzada."}},
{n:83,q:"A efectos de reforma constitucional, las materias que gozan de especial protección son las referidas a:",o:{a:"Los principios generales fundamentales.",b:"Los derechos fundamentales y libertades públicas.",c:"La Corona.",d:"Todas las anteriores son materias que gozan de especial protección."},correct:"d",why:{"d":"Las tres materias indicadas gozan de especial protección constitucional: los principios del Título Preliminar (Estado social y democrático de Derecho, valores superiores, etc.), los derechos fundamentales de la Sección 1ª Cap. 2 Título I, y la institución de la Corona (Título II)."}},
{n:84,q:"La iniciativa de reforma constitucional se ejercerá en los términos previstos:",o:{a:"En los apartados 1 y 2 del artículo 87 de la Constitución.",b:"En la Ley Orgánica del Régimen Electoral General.",c:"Las respuestas a) y b) son correctas.",d:"Las respuestas a) y b) son incorrectas."},correct:"a",why:{"a":"El artículo 166 CE remite al artículo 87, apartados 1 y 2, para la iniciativa de reforma constitucional (Gobierno, Congreso, Senado y Asambleas Legislativas de CCAA). El apartado 3 del art. 87 (iniciativa popular) está expresamente excluido."}},
{n:85,q:"La reforma total de la Constitución, o la parcial que afecte a materias especialmente protegidas, se aprobará inicialmente por:",o:{a:"Mayoría de 2/3 de cada Cámara.",b:"Mayoría de 3/4 de cada Cámara.",c:"Mayoría de 3/5 de cada Cámara.",d:"Mayoría absoluta de cada Cámara."},correct:"a",why:{"a":"El artículo 168.1 CE establece que la reforma total o de materias especialmente protegidas debe aprobarse inicialmente por mayoría de 2/3 de cada Cámara, lo que desencadena la disolución inmediata de las Cortes y el proceso de ratificación por las nuevas Cámaras."}},
{n:86,q:"Aprobada inicialmente la reforma total de la Constitución, o parcial que afecte a materias especialmente protegidas...",o:{a:"Se convocará referéndum.",b:"Se disolverán de manera inmediata las Cortes Generales.",c:"Se procederá a la elección de nuevo Presidente del Gobierno conforme al procedimiento previsto en el artículo 98 de la Constitución Española.",d:"Se convocará a la Comisión Constitucional del Congreso."},correct:"b",why:{"b":"El artículo 168.1 CE establece que tras la aprobación inicial por mayoría de 2/3 de cada Cámara, las Cortes Generales quedan disueltas de forma inmediata, procediéndose a nuevas elecciones generales para que las nuevas Cámaras ratifiquen la reforma."}},
{n:87,q:"En caso de reforma total de la Constitución, o parcial que afecte a materias especialmente protegidas, tras la aprobación inicial y disolución de las Cortes, las nuevas Cámaras elegidas deben ratificar la decisión con una mayoría de:",o:{a:"3/5 de cada Cámara.",b:"2/3 de cada Cámara.",c:"Mayoría absoluta de cada Cámara.",d:"3/4 de cada Cámara."},correct:"b",why:{"b":"El artículo 168.2 CE exige que las nuevas Cortes elegidas tras la disolución ratifiquen la decisión de reforma por mayoría de 2/3 de cada Cámara. Esta doble exigencia (aprobación inicial + ratificación por nuevas Cortes + referendum) hace del procedimiento agravado uno de los más exigentes de Europa."}},
{n:88,q:"La reforma total de la Constitución, o parcial que afecte a materias especialmente protegidas:",o:{a:"Debe ser sometida a referéndum.",b:"Podrá ser sometida a referéndum si lo solicitan una décima parte de los diputados.",c:"Debe ser sometida a referéndum si lo solicitan una décima parte de los diputados.",d:"No necesita ser sometida a referéndum."},correct:"a",why:{"a":"El artículo 168.3 CE establece que la reforma de materias especialmente protegidas \'será sometida a referéndum para su ratificación\'. En este caso, el referéndum es OBLIGATORIO, a diferencia de la reforma ordinaria del art. 167 donde el referéndum es facultativo."}},
{n:89,q:"Los proyectos de reforma parcial ordinaria de la Constitución (reforma que no afecta a materias dotadas de especial protección), requieren:",o:{a:"Aprobación por mayoría de 3/5 de cada Cámara.",b:"Aprobación por mayoría de 2/5 de cada Cámara.",c:"Aprobación por mayoría absoluta de cada Cámara.",d:"Aprobación por mayoría de 2/3 de cada Cámara."},correct:"a",why:{"a":"El artículo 167.1 CE establece que los proyectos de reforma constitucional ordinaria deberán ser aprobados por mayoría de 3/5 de cada una de las Cámaras. Si no hay acuerdo, se intenta por una Comisión Mixta paritaria."}},
{n:90,q:"En los proyectos de reforma constitucional parcial ordinaria (reforma que no afecta a materias dotadas de especial protección), si no hubiera acuerdo entre ambas Cámaras, se intentará obtenerlo mediante:",o:{a:"Referéndum consultivo.",b:"La creación de una Comisión Mixta paritaria de Diputados y Senadores.",c:"La aprobación del Congreso por mayoría absoluta.",d:"La convocatoria de nuevas elecciones."},correct:"b",why:{"b":"El artículo 167.1 CE establece que si no hay acuerdo entre el Congreso y el Senado, se intentará obtener mediante la creación de una Comisión Mixta paritaria de Diputados y Senadores, que presentará un texto para su votación en cada Cámara."}},
{n:91,q:"En los proyectos de reforma constitucional parcial ordinaria (reforma que no afecta a materias dotadas de especial protección), de no lograrse la aprobación preceptiva del texto presentado por la Comisión Mixta paritaria, éste se entenderá aprobado si hubiere obtenido el voto favorable de:",o:{a:"Mayoría absoluta del Senado y mayoría de 2/3 del Congreso.",b:"Mayoría absoluta del Congreso y mayoría de 2/3 del Senado.",c:"Mayoría absoluta del Congreso.",d:"Mayoría absoluta del Senado y mayoría absoluta del Congreso."},correct:"a",why:{"a":"El artículo 167.2 CE establece que si el texto de la Comisión Mixta no obtiene los 3/5 en ambas Cámaras, se entenderá aprobado si el Senado lo aprueba por mayoría absoluta y el Congreso por mayoría de 2/3."}},
{n:92,q:"La reforma parcial ordinaria de la Constitución (reforma que no afecta a materias dotadas de especial protección), no precisa someterse a referéndum para su ratificación, salvo que:",o:{a:"Lo solicite la mayoría absoluta del Congreso.",b:"Lo solicite el Gobierno.",c:"Lo solicite la mayoría absoluta del Senado.",d:"Lo solicite la décima parte de los miembros de cualquiera de las Cámaras."},correct:"d",why:{"d":"El artículo 167.3 CE establece que la reforma ordinaria no precisa referéndum, salvo que en los quince días siguientes a su aprobación lo soliciten una décima parte de los miembros de cualquiera de las Cámaras (Congreso o Senado)."}},
{n:93,q:"Para proceder a la reforma del Título VIII de la Constitución, en lo relativo a las competencias de las Comunidades Autónomas, se precisa:",o:{a:"Mayoría de 3/5 de cada Cámara, pudiendo ser aprobada, en caso de desacuerdo, con la mayoría absoluta del Congreso y mayoría de 2/3 del Senado.",b:"Mayoría de 3/5 de cada Cámara, pudiendo ser aprobada, en caso de desacuerdo, con la mayoría absoluta del Senado y mayoría de 2/3 del Congreso.",c:"Mayoría absoluta del Congreso y del Senado.",d:"Mayoría absoluta del Congreso.."},correct:"b",why:{"b":"La reforma del Título VIII en materia de competencias autonómicas se rige por el procedimiento ordinario del art. 167 CE: 3/5 de cada Cámara, o en desacuerdo, mayoría absoluta del Senado y 2/3 del Congreso (no al revés)."}},
{n:94,q:"No necesita someterse a referéndum:",o:{a:"La reforma del Título II de la Constitución.",b:"La reforma del sistema de derechos y libertades recogidos en la Constitución.",c:"La reforma del Capítulo Segundo, Sección 2ª, del Título I de la Constitución.",d:"La reforma del Capítulo Segundo, Sección 1ª, del Título I de la Constitución."},correct:"c",why:{"c":"La Sección 2ª del Capítulo 2 del Título I (arts. 30-38: derechos y deberes de los ciudadanos) se reforma por el procedimiento ordinario del art. 167, para el cual el referéndum es facultativo (no obligatorio). La Sección 1ª (derechos fundamentales) y el Título II (Corona) sí requieren el procedimiento agravado con referéndum obligatorio."}},
{n:95,q:"¿Cuál de las siguientes propuestas de reforma Constitucional necesita ser sometida a referéndum de manera obligatoria?",o:{a:"La del Título VIII.",b:"La de cualquiera de los preceptos contenidos en el Título I.",c:"La del Título III.",d:"La del artículo 9 de la Constitución."},correct:"d",why:{"d":"El artículo 9 de la CE forma parte del Título Preliminar, que es una de las materias especialmente protegidas del artículo 168. Por tanto, cualquier reforma del art. 9 requiere el procedimiento agravado con referéndum obligatorio. Los Títulos III y VIII no están en esa categoría, y el Título I solo en su Capítulo 2, Sección 1ª."}},
{n:96,q:"La aprobación inicial de la reforma de la Constitución por mayoría de 2/3 de cada Cámara y la disolución inmediata de las Cortes:",o:{a:"Tiene lugar en supuestos de reforma total de la Constitución, o del Título Preliminar de ésta.",b:"Es suficiente para reformar cualquier precepto de la Constitución, sin necesidad de otro trámite.",c:"Tiene lugar cuando se pretende reformar lo referente a las competencias de municipios y provincias.",d:"Podrá realizarse cuando esté declarado el estado de alarma, pero no cuando estén declarados los estados de excepción o de sitio."},correct:"a",why:{"a":"La aprobación por 2/3 y la disolución inmediata de las Cortes (procedimiento agravado del art. 168 CE) tiene lugar en caso de reforma total de la Constitución o cuando se reforma alguna de las materias especialmente protegidas: Título Preliminar, Sección 1ª Cap. 2 Título I o Título II."}}
];